/* RedRoom Fitness - Dark Bold Corporate Website Styles */

:root {
  --primary: #E63946;
  --primary-dark: #c62833;
  --bg-dark: #111111;
  --bg-card: #1a1a1a;
  --bg-light: #222222;
  --text-white: #ffffff;
  --text-gray: #b0b0b0;
  --text-dark-gray: #888888;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-white);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Navigation */
.top-bar {
  background: var(--primary);
  padding: 8px 20px;
  text-align: center;
  font-size: 14px;
}

.top-bar a {
  color: var(--text-white);
  text-decoration: none;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.main-nav {
  background: var(--bg-dark);
  padding: 20px 40px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #333;
}

.logo {
  font-family: 'Oswald', sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--primary);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.nav-links {
  display: flex;
  gap: 30px;
  list-style: none;
}

.nav-links a {
  color: var(--text-white);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  transition: color 0.3s;
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 15px;
}

.btn {
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: none;
  cursor: pointer;
  text-decoration: none;
  display: inline-block;
  transition: all 0.3s;
}

.btn-primary {
  background: var(--primary);
  color: var(--text-white);
}

.btn-primary:hover {
  background: var(--primary-dark);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--text-white);
}

/* Hero Section */
.hero {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 60px 20px;
  position: relative;
  background: linear-gradient(180deg, rgba(17,17,17,0.7) 0%, rgba(17,17,17,1) 100%);
}

.hero h1 {
  font-size: clamp(48px, 8vw, 80px);
  margin-bottom: 20px;
  line-height: 1.1;
}

.hero-subtitle {
  font-size: 18px;
  color: var(--text-gray);
  max-width: 600px;
  margin-bottom: 40px;
}

.hero-ctas {
  display: flex;
  gap: 20px;
}

/* Section Styles */
section {
  padding: 80px 40px;
}

.section-title {
  font-size: clamp(32px, 5vw, 48px);
  margin-bottom: 20px;
  text-align: center;
}

.section-subtitle {
  text-align: center;
  color: var(--text-gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 18px;
}

/* Community Promo */
.community-promo {
  background: var(--bg-card);
  text-align: center;
}

.community-promo h2 {
  color: var(--primary);
}

/* Two Ways Section */
.two-ways {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.way-card {
  background: var(--bg-card);
  padding: 40px;
  text-align: center;
  border: 1px solid #333;
  transition: border-color 0.3s;
}

.way-card:hover {
  border-color: var(--primary);
}

.way-card h3 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 28px;
}

/* Studio Experience */
.studio-exp {
  background: var(--bg-card);
  text-align: center;
}

.studio-exp p {
  max-width: 700px;
  margin: 0 auto 40px;
  font-size: 18px;
  color: var(--text-gray);
}

/* Free Trial CTA */
.free-trial-cta {
  background: linear-gradient(135deg, var(--primary) 0%, #8b0000 100%);
  text-align: center;
}

.free-trial-cta h2 {
  font-size: clamp(36px, 5vw, 56px);
  margin-bottom: 30px;
}

.free-trial-cta .btn {
  background: var(--bg-dark);
  color: var(--text-white);
  font-size: 18px;
  padding: 18px 40px;
}

.free-trial-cta .btn:hover {
  background: var(--bg-light);
}

/* Carousel */
.carousel-section {
  padding: 80px 0;
  background: var(--bg-dark);
}

.carousel {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: var(--text-gray);
}

.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--primary);
  border: none;
  color: white;
  font-size: 24px;
  width: 50px;
  height: 50px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-nav:hover {
  background: var(--primary-dark);
}

.carousel-prev { left: 20px; }
.carousel-next { right: 20px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #444;
  border: none;
  cursor: pointer;
  transition: background 0.3s;
}

.carousel-dot.active {
  background: var(--primary);
}

/* Newsletter */
.newsletter {
  background: var(--bg-card);
  text-align: center;
}

.newsletter-form {
  max-width: 500px;
  margin: 0 auto;
  display: flex;
  gap: 10px;
}

.newsletter-form input {
  flex: 1;
  padding: 15px 20px;
  background: var(--bg-dark);
  border: 1px solid #333;
  color: var(--text-white);
  font-size: 16px;
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary);
}

.newsletter-form input.error {
  border-color: #ff4444;
}

.newsletter-message {
  margin-top: 15px;
  font-size: 14px;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: #ff4444;
}

/* Footer */
footer {
  background: #0a0a0a;
  padding: 60px 40px 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-gray);
  text-decoration: none;
  font-size: 14px;
  transition: color 0.3s;
}

.footer-col a:hover {
  color: var(--text-white);
}

.footer-bottom {
  text-align: center;
  padding-top: 40px;
  margin-top: 40px;
  border-top: 1px solid #333;
  color: var(--text-dark-gray);
  font-size: 14px;
}

/* Country Selector */
.country-selector {
  margin-top: 20px;
  position: relative;
  display: inline-block;
}

.country-selector button {
  background: var(--bg-card);
  border: 1px solid #333;
  color: var(--text-white);
  padding: 10px 15px;
  cursor: pointer;
  font-size: 14px;
}

.country-selector button:hover {
  border-color: var(--primary);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-card);
  border: 1px solid #333;
  min-width: 150px;
  display: none;
  z-index: 100;
}

.country-dropdown.show {
  display: block;
}

.country-dropdown a {
  display: block;
  padding: 10px 15px;
  color: var(--text-gray);
  text-decoration: none;
}

.country-dropdown a:hover {
  background: var(--bg-light);
  color: var(--text-white);
}

/* Page Hero */
.page-hero {
  padding: 120px 40px 80px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-card) 0%, var(--bg-dark) 100%);
}

.page-hero h1 {
  font-size: clamp(40px, 6vw, 64px);
  margin-bottom: 20px;
}

.page-hero p {
  color: var(--text-gray);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* Toggle Switch */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}

.toggle-btn {
  padding: 15px 40px;
  background: var(--bg-card);
  border: 2px solid var(--primary);
  color: var(--text-gray);
  font-size: 16px;
  font-weight: 600;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.3s;
}

.toggle-btn:first-child {
  border-right: none;
}

.toggle-btn:last-child {
  border-left: none;
}

.toggle-btn.active {
  background: var(--primary);
  color: var(--text-white);
}

.toggle-content {
  display: none;
  max-width: 800px;
  margin: 0 auto;
  padding: 40px;
  background: var(--bg-card);
}

.toggle-content.active {
  display: block;
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  border-collapse: collapse;
}

.schedule-table th,
.schedule-table td {
  padding: 20px;
  text-align: left;
  border-bottom: 1px solid #333;
}

.schedule-table th {
  color: var(--primary);
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.schedule-table td {
  font-size: 16px;
}

.schedule-table tr:hover {
  background: var(--bg-card);
}

/* Filter Controls */
.filter-controls {
  text-align: center;
  margin-bottom: 40px;
}

.filter-controls select {
  padding: 12px 20px;
  background: var(--bg-card);
  border: 1px solid #333;
  color: var(--text-white);
  font-size: 14px;
  min-width: 200px;
  cursor: pointer;
}

.filter-controls select:focus {
  outline: none;
  border-color: var(--primary);
}

/* Instructor Grid */
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid #333;
  overflow: hidden;
  transition: border-color 0.3s, transform 0.3s;
}

.instructor-card:hover {
  border-color: var(--primary);
  transform: translateY(-5px);
}

.instructor-img {
  width: 100%;
  aspect-ratio: 1;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  color: var(--primary);
}

.instructor-info {
  padding: 25px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 8px;
}

.instructor-info .location {
  color: var(--primary);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 15px;
}

.instructor-info .book-link {
  color: var(--text-gray);
  text-decoration: none;
  font-size: 14px;
}

.instructor-info .book-link:hover {
  color: var(--primary);
}

/* FAQ Accordion */
.faq-container {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid #333;
}

.faq-question {
  width: 100%;
  padding: 25px 0;
  background: transparent;
  border: none;
  color: var(--text-white);
  font-size: 18px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question::after {
  content: '+';
  font-size: 24px;
  color: var(--primary);
  transition: transform 0.3s;
}

.faq-item.open .faq-question::after {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
  padding-bottom: 25px;
}

.faq-answer p {
  color: var(--text-gray);
  line-height: 1.8;
}

/* Feature Blocks */
.feature-blocks {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
}

.feature-block {
  background: var(--bg-card);
  padding: 40px;
  border: 1px solid #333;
  transition: border-color 0.3s;
}

.feature-block:hover {
  border-color: var(--primary);
}

.feature-block h3 {
  color: var(--primary);
  font-size: 24px;
  margin-bottom: 15px;
}

.feature-block p {
  color: var(--text-gray);
  line-height: 1.7;
}

/* CTA Section */
.cta-section {
  text-align: center;
  padding: 100px 40px;
}

.cta-section h2 {
  font-size: clamp(32px, 5vw, 48px);
  margin-bottom: 20px;
}

.cta-section p {
  color: var(--text-gray);
  margin-bottom: 40px;
  font-size: 18px;
}

/* Responsive */
@media (max-width: 768px) {
  .main-nav {
    flex-direction: column;
    gap: 20px;
    padding: 20px;
  }

  .nav-links {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero-ctas {
    flex-direction: column;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 14px;
  }

  section {
    padding: 60px 20px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }
}

/* Utility Classes */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.text-center { text-align: center; }
.text-primary { color: var(--primary); }
.mt-40 { margin-top: 40px; }
.mb-40 { margin-bottom: 40px; }

