/* RedRoom Fitness - Dark Bold Corporate Website Styles */

:root {
  --primary: #E63946;
  --primary-dark: #c62833;
  --bg-dark: #111111;
  --bg-card: #1a1a1a;
  --bg-light: #222222;
  --text-white: #ffffff;
  --text-gray: #b0b0b0;
  --text-dark-gray: #888888;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--bg-dark);
  color: var(--text-white);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
