  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.main-nav {
  background: var(--bg-dark);
  padding: 20px 40px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #333;
