section {
  padding: 80px 40px;
}

.section-title {
  font-size: clamp(32px, 5vw, 48px);
  margin-bottom: 20px;
  text-align: center;
}

.section-subtitle {
  text-align: center;
  color: var(--text-gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 18px;
}

/* Community Promo */
.community-promo {
  background: var(--bg-card);
  text-align: center;
}

.community-promo h2 {
  color: var(--primary);
}

/* Two Ways Section */
.two-ways {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.way-card {
  background: var(--bg-card);
  padding: 40px;
  text-align: center;
  border: 1px solid #333;
  transition: border-color 0.3s;
}

.way-card:hover {
  border-color: var(--primary);
}

.way-card h3 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 28px;
}

/* Studio Experience */
.studio-exp {
  background: var(--bg-card);
  text-align: center;
}

.studio-exp p {
  max-width: 700px;
  margin: 0 auto 40px;
  font-size: 18px;
  color: var(--text-gray);
}

