  background: linear-gradient(135deg, var(--primary) 0%, #8b0000 100%);
  text-align: center;
}

.free-trial-cta h2 {
  font-size: clamp(36px, 5vw, 56px);
  margin-bottom: 30px;
}

.free-trial-cta .btn {
  background: var(--bg-dark);
  color: var(--text-white);
