  padding: 15px 20px;
  background: var(--bg-dark);
  border: 1px solid #333;
  color: var(--text-white);
  font-size: 16px;
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary);
}

.newsletter-form input.error {
  border-color: #ff4444;
}

.newsletter-message {
  margin-top: 15px;
  font-size: 14px;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: #ff4444;
}

/* Footer */
footer {
  background: #0a0a0a;
  padding: 60px 40px 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-gray);
  text-decoration: none;
  font-size: 14px;
  transition: color 0.3s;
}

.footer-col a:hover {
  color: var(--text-white);
}

.footer-bottom {
  text-align: center;
  padding-top: 40px;
