  background: var(--bg-card);
  border: 1px solid #333;
  color: var(--text-white);
  padding: 10px 15px;
  cursor: pointer;
  font-size: 14px;
}

.country-selector button:hover {
  border-color: var(--primary);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-card);
  border: 1px solid #333;
  min-width: 150px;
  display: none;
  z-index: 100;
}

.country-dropdown.show {
  display: block;
}

.country-dropdown a {
  display: block;
  padding: 10px 15px;
  color: var(--text-gray);
  text-decoration: none;
}

.country-dropdown a:hover {
  background: var(--bg-light);
  color: var(--text-white);
}

