  font-size: clamp(40px, 6vw, 64px);
  margin-bottom: 20px;
}

.page-hero p {
  color: var(--text-gray);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* Toggle Switch */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}

.toggle-btn {
  padding: 15px 40px;
  background: var(--bg-card);
  border: 2px solid var(--primary);
  color: var(--text-gray);
  font-size: 16px;
  font-weight: 600;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.3s;
}

.toggle-btn:first-child {
  border-right: none;
}

.toggle-btn:last-child {
  border-left: none;
}

.toggle-btn.active {
  background: var(--primary);
  color: var(--text-white);
}

.toggle-content {
  display: none;
  max-width: 800px;
  margin: 0 auto;
  padding: 40px;
  background: var(--bg-card);
}

.toggle-content.active {
  display: block;
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  border-collapse: collapse;
}

.schedule-table th,
.schedule-table td {
  padding: 20px;
