section {
  padding: 80px 40px;
}

.section-title {
  font-size: clamp(32px, 5vw, 48px);
  margin-bottom: 20px;
  text-align: center;
}

.section-subtitle {
  text-align: center;
  color: var(--text-gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 18px;
}

/* Community Promo */
.community-promo {
  background: var(--bg-card);
  text-align: center;
}

.community-promo h2 {
  color: var(--primary);
}

/* Two Ways Section */
.two-ways {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.way-card {
  background: var(--bg-card);
  padding: 40px;
  text-align: center;
  border: 1px solid #333;
  transition: border-color 0.3s;
}

.way-card:hover {
  border-color: var(--primary);
}

.way-card h3 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 28px;
}

/* Studio Experience */
.studio-exp {
  background: var(--bg-card);
  text-align: center;
}

.studio-exp p {
  max-width: 700px;
  margin: 0 auto 40px;
  font-size: 18px;
  color: var(--text-gray);
}

/* Free Trial CTA */
.free-trial-cta {
  background: linear-gradient(135deg, var(--primary) 0%, #8b0000 100%);
  text-align: center;
}

.free-trial-cta h2 {
  font-size: clamp(36px, 5vw, 56px);
  margin-bottom: 30px;
}

.free-trial-cta .btn {
  background: var(--bg-dark);
  color: var(--text-white);
  font-size: 18px;
  padding: 18px 40px;
}

.free-trial-cta .btn:hover {
  background: var(--bg-light);
}

/* Carousel */
.carousel-section {
  padding: 80px 0;
  background: var(--bg-dark);
}

.carousel {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: var(--text-gray);
}

.carousel-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--primary);
  border: none;
  color: white;
  font-size: 24px;
  width: 50px;
  height: 50px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-nav:hover {
  background: var(--primary-dark);
}

.carousel-prev { left: 20px; }
.carousel-next { right: 20px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #444;
  border: none;
  cursor: pointer;
  transition: background 0.3s;
}

.carousel-dot.active {
  background: var(--primary);
}

/* Newsletter */
.newsletter {
  background: var(--bg-card);
  text-align: center;
}

.newsletter-form {
  max-width: 500px;
  margin: 0 auto;
  display: flex;
  gap: 10px;
}

.newsletter-form input {
  flex: 1;
  padding: 15px 20px;
  background: var(--bg-dark);
  border: 1px solid #333;
  color: var(--text-white);
  font-size: 16px;
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary);
}

.newsletter-form input.error {
  border-color: #ff4444;
}

.newsletter-message {
  margin-top: 15px;
  font-size: 14px;
}

.newsletter-message.success {
  color: #4CAF50;
}

.newsletter-message.error {
  color: #ff4444;
}

