footer {
  background: #0a0a0a;
  padding: 60px 40px 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  color: var(--primary);
  margin-bottom: 20px;
  font-size: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-gray);
  text-decoration: none;
  font-size: 14px;
  transition: color 0.3s;
}

.footer-col a:hover {
  color: var(--text-white);
}

.footer-bottom {
  text-align: center;
  padding-top: 40px;
  margin-top: 40px;
  border-top: 1px solid #333;
  color: var(--text-dark-gray);
  font-size: 14px;
}

/* Country Selector */
.country-selector {
  margin-top: 20px;
  position: relative;
  display: inline-block;
}

.country-selector button {
  background: var(--bg-card);
  border: 1px solid #333;
  color: var(--text-white);
  padding: 10px 15px;
  cursor: pointer;
  font-size: 14px;
}

.country-selector button:hover {
  border-color: var(--primary);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-card);
  border: 1px solid #333;
  min-width: 150px;
  display: none;
  z-index: 100;
}

.country-dropdown.show {
  display: block;
}

.country-dropdown a {
  display: block;
  padding: 10px 15px;
  color: var(--text-gray);
  text-decoration: none;
}

.country-dropdown a:hover {
  background: var(--bg-light);
  color: var(--text-white);
}

/* Page Hero */
.page-hero {
  padding: 120px 40px 80px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-card) 0%, var(--bg-dark) 100%);
}

.page-hero h1 {
  font-size: clamp(40px, 6vw, 64px);
  margin-bottom: 20px;
}

.page-hero p {
  color: var(--text-gray);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* Toggle Switch */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}

.toggle-btn {
  padding: 15px 40px;
  background: var(--bg-card);
  border: 2px solid var(--primary);
  color: var(--text-gray);
  font-size: 16px;
  font-weight: 600;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.3s;
}

.toggle-btn:first-child {
  border-right: none;
}

.toggle-btn:last-child {
  border-left: none;
}

.toggle-btn.active {
  background: var(--primary);
  color: var(--text-white);
}

.toggle-content {
  display: none;
  max-width: 800px;
  margin: 0 auto;
  padding: 40px;
  background: var(--bg-card);
}

.toggle-content.active {
  display: block;
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  border-collapse: collapse;
}

.schedule-table th,
.schedule-table td {
  padding: 20px;
  text-align: left;
  border-bottom: 1px solid #333;
}

.schedule-table th {
  color: var(--primary);
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.schedule-table td {
  font-size: 16px;
}

.schedule-table tr:hover {
  background: var(--bg-card);
}

/* Filter Controls */
.filter-controls {
  text-align: center;
  margin-bottom: 40px;
}

.filter-controls select {
  padding: 12px 20px;
  background: var(--bg-card);
  border: 1px solid #333;
  color: var(--text-white);
  font-size: 14px;
  min-width: 200px;
  cursor: pointer;
}

.filter-controls select:focus {
  outline: none;
  border-color: var(--primary);
}

/* Instructor Grid */
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid #333;
  overflow: hidden;
  transition: border-color 0.3s, transform 0.3s;
}

.instructor-card:hover {
  border-color: var(--primary);
  transform: translateY(-5px);
}

.instructor-img {
  width: 100%;
  aspect-ratio: 1;
  background: var(--bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  color: var(--primary);
}

.instructor-info {
  padding: 25px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 8px;
}

.instructor-info .location {
  color: var(--primary);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 15px;
}

.instructor-info .book-link {
  color: var(--text-gray);
  text-decoration: none;
  font-size: 14px;
}

.instructor-info .book-link:hover {
  color: var(--primary);
}

/* FAQ Accordion */
.faq-container {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid #333;
}

.faq-question {
  width: 100%;
  padding: 25px 0;
  background: transparent;
  border: none;
  color: var(--text-white);
  font-size: 18px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question::after {
  content: '+';
  font-size: 24px;
  color: var(--primary);
  transition: transform 0.3s;
}

.faq-item.open .faq-question::after {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
  padding-bottom: 25px;
}

.faq-answer p {
  color: var(--text-gray);
  line-height: 1.8;
}

/* Feature Blocks */
.feature-blocks {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
}

.feature-block {
  background: var(--bg-card);
  padding: 40px;
  border: 1px solid #333;
  transition: border-color 0.3s;
}

.feature-block:hover {
  border-color: var(--primary);
}

.feature-block h3 {
  color: var(--primary);
  font-size: 24px;
  margin-bottom: 15px;
}

.feature-block p {
  color: var(--text-gray);
  line-height: 1.7;
}

/* CTA Section */
.cta-section {
  text-align: center;
  padding: 100px 40px;
}

.cta-section h2 {
  font-size: clamp(32px, 5vw, 48px);
  margin-bottom: 20px;
}

.cta-section p {
  color: var(--text-gray);
  margin-bottom: 40px;
  font-size: 18px;
}

/* Responsive */
@media (max-width: 768px) {
  .main-nav {
    flex-direction: column;
    gap: 20px;
    padding: 20px;
  }

  .nav-links {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero-ctas {
    flex-direction: column;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 14px;
  }

  section {
    padding: 60px 20px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }
}

/* Utility Classes */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.text-center { text-align: center; }
.text-primary { color: var(--primary); }
.mt-40 { margin-top: 40px; }
.mb-40 { margin-bottom: 40px; }

